
import React, { useState } from 'react';

// ---------------------------------------------------------------------------
// ARAHAN: Masukkan string Base64 imej anda di sini untuk menggantikan icon.
// Anda boleh convert imej di: https://www.base64-image.de/
// Format contoh: "data:image/png;base64,iVBORw0KGgo..."
// Jika dibiarkan kosong (""), logo fallback (bentuk geometri) akan dipaparkan.
// ---------------------------------------------------------------------------

const LIGHT_MODE_BASE64 = "data:image/png;base64,"; // Paste string Base64 untuk Light Mode di sini
const DARK_MODE_BASE64 = "data:image/png;base64,";  // Paste string Base64 untuk Dark Mode di sini

interface LogoProps extends React.HTMLAttributes<HTMLDivElement> {
  className?: string;
}

export const Logo: React.FC<LogoProps> = ({ className = "w-10 h-10", ...props }) => {
  const [imgError, setImgError] = useState(false);
  
  // Filter out potential SVG-specific props like fill/stroke to avoid React warnings on the div
  const { ...validProps } = props as any;
  delete validProps.fill;
  delete validProps.stroke;

  // Gunakan Fallback SVG jika:
  // 1. Berlaku ralat loading imej (imgError)
  // 2. String Base64 masih kosong
  const useFallback = imgError || !LIGHT_MODE_BASE64 || !DARK_MODE_BASE64;

  if (useFallback) {
    return (
      <div className={`${className} flex items-center justify-center select-none text-primary`} {...validProps}>
        <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full">
            <path d="M12 2L2 7l10 5 10-5-10-5zm0 9l2.5-1.25L12 8.5l-2.5 1.25L12 11zm0 2.5l-5-2.5-5 2.5L12 22l10-8.5-5-2.5-5 2.5z" />
        </svg>
      </div>
    );
  }

  return (
    <div className={`relative ${className} flex items-center justify-center select-none`} {...validProps}>
      {/* Light Mode Logo (Base64) */}
      <img 
        src={LIGHT_MODE_BASE64} 
        alt="FinelySync Logo" 
        className="w-full h-full object-contain block dark:hidden select-none pointer-events-none" 
        draggable={false}
        onError={() => setImgError(true)}
      />
      
      {/* Dark Mode Logo (Base64) */}
      <img 
        src={DARK_MODE_BASE64} 
        alt="FinelySync Logo" 
        className="w-full h-full object-contain hidden dark:block select-none pointer-events-none" 
        draggable={false}
        onError={() => setImgError(true)}
      />
    </div>
  );
};
